head.script:
// 테스트 설명, 유효성 값 설정 (_1: get* 메서드 반환값에 separator 적용 검증)
scwin.tData = {
    "description" : "[multiselect > P > separator]<br/>Multiselect 컴포넌트에서 두 개 이상의 아이템을 선택했을때 Value 값을 구분하는 구분자를 설정합니다.",
    "validation" : [
        "선택된 각 아이템의 Value 값을 구분하는 구분자를 텍스트로 설정합니다.",
        "값을 설정하지 않으면 ' '(Space)가 적용됩니다.",
        "한 개의 아이템이 선택된 경우 컴포넌트의 Value 값에 구분자가 포함되지 않습니다.",
        "getValue(), getText(), getSelectedIndex(), getAllValue() 메소드의 반환값에 separator 구분자가 사용됩니다.",
        "getValue(delimeter), getText(delimeter), getSelectedIndex(delimeter) 메소드는 인자로 전달된 구분자가 separator 속성보다 우선 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, separator 속성 적용)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createDataListMultiSelect();

    let cSeparator = con_separator.getText();

    let properties = {};
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="target1 : separator=[' + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + ']"', '', 'label1');
    $c.gcm.createBasicMultiSelect(cList);
};



// 두 개 이상 선택 (인덱스 0, 2)
scwin.btn_selectTwo_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(0, true);
    target1.setSelectedIndexNM(2, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 0, 2 아이템 선택 완료");
};



// 한 개만 선택 (인덱스 1)
scwin.btn_selectOne_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(1, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 1 아이템만 선택 완료");
};



// getValue() - separator 속성값 사용
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue() : [" + target1.getValue() + "]");
};



// getValue('|') - 인자 구분자가 separator 속성보다 우선
scwin.btn_getValueDelim_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue('|') : [" + target1.getValue("|") + "]");
};



// getText() - separator 속성값 사용
scwin.btn_getText_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getText() : [" + target1.getText() + "]");
};



// getSelectedIndex() - separator 속성값 사용
scwin.btn_getSelectedIndex_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};



// getAllValue() - separator 속성값 사용
scwin.btn_getAllValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getAllValue() : [" + target1.getAllValue() + "]");
};
